@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#12141d;--paper:#f6f1e7;--muted:#a9a9b5;--orange:#ffb33e;--coral:#ff645b;--cyan:#62e1e2;--panel:rgba(20,22,32,.88)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#151720;color:white;font-family:'DM Sans',sans-serif}button,input{font:inherit}button{color:inherit;cursor:pointer}#app{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#191d27}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 34%,rgba(9,10,16,.22) 100%),linear-gradient(180deg,rgba(8,10,17,.34),transparent 28%,transparent 73%,rgba(8,10,15,.53));z-index:1}.screen,.modal,.match-hud{position:absolute;inset:0;z-index:2}.screen{background:linear-gradient(100deg,rgba(14,15,23,.91) 0%,rgba(14,15,23,.73) 39%,rgba(14,15,23,.13) 76%,rgba(14,15,23,.17));}.topbar{height:92px;display:flex;align-items:center;justify-content:space-between;padding:0 6.1vw;border-bottom:1px solid rgba(255,255,255,.1)}.brand{font-family:'Barlow Condensed',sans-serif;font-size:26px;font-weight:900;letter-spacing:1.6px;display:flex;align-items:center;gap:11px}.brand-light{font-weight:600;color:#f4d8a4}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:var(--orange);color:#24232a;font-size:21px;box-shadow:0 4px 20px #ffae3855}.profile{display:flex;align-items:center;gap:10px;font-size:12px;font-weight:700;color:#fff}.profile small{display:block;color:#9da1ad;font-size:9px;letter-spacing:1px;margin-top:3px}.profile b{font-size:19px;color:#b8bac5;margin-left:19px}.avatar{display:grid;place-items:center;width:34px;height:34px;background:#423b4b;border:1px solid #6c6372;border-radius:50%;color:var(--orange)}.hero-copy{position:absolute;left:8.2%;top:20.1%;}.eyebrow{font-size:10px;font-weight:800;letter-spacing:2.5px;color:#ffbe52;display:flex;align-items:center;gap:9px}.eyebrow i{width:7px;height:7px;border-radius:100%;background:#ff655a;box-shadow:0 0 12px #ff655a}.hero-copy h1{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:clamp(72px,9vw,132px);line-height:.77;letter-spacing:-2px;margin:22px 0 19px;text-shadow:0 7px 30px #090a10aa}.hero-copy h1 em{font-style:normal;color:var(--orange)}.hero-copy p{color:#c4c4ca;font-size:14px;line-height:1.65;margin:0}.home-bottom{position:absolute;left:8.2%;bottom:7.6%;display:flex;gap:42px;align-items:flex-end}.home-card{width:302px;background:rgba(22,24,34,.82);border:1px solid rgba(255,255,255,.14);border-radius:11px;padding:17px 18px 15px;box-shadow:0 16px 46px #07080d66;backdrop-filter:blur(16px)}.card-label,.stats span{font-size:9px;font-weight:800;letter-spacing:1.5px;color:#9da0ab}.picked-row{display:flex;align-items:center;gap:12px;margin:12px 0 15px}.picked-portrait{width:48px;height:48px;border-radius:12px;background:linear-gradient(145deg,#ffcf75,#dc684e);display:grid;place-items:center;font-size:28px;color:#382d33;text-shadow:0 2px 0 #fff6;box-shadow:inset 0 -7px 13px #7f3b3d44}.picked-row h2{font-family:'Barlow Condensed';font-size:25px;margin:0 0 2px;letter-spacing:.3px}.picked-row span{font-size:8px;letter-spacing:1px;color:#b4b4c0;font-weight:700}.change-btn{margin-left:auto;background:transparent;border:0;color:#d4d4db;font-size:9px;font-weight:800;letter-spacing:1.1px}.change-btn b{font-size:15px;color:var(--orange);margin-left:4px}.stats{display:grid;gap:8px}.stats>div{display:grid;grid-template-columns:52px 1fr;align-items:center;gap:8px}.stats span{font-size:8px}.stat-track{height:4px;border-radius:4px;background:#ffffff20;overflow:hidden}.stat-track b{height:100%;display:block;background:var(--orange);border-radius:4px}.stat-track.power b{background:#ff665b}.stat-track.speed b{background:#62dadd}.play-block{width:294px}.mode-row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.mode-icon{font-size:25px;color:var(--cyan)}.mode-row b{font-size:11px;letter-spacing:1px}.mode-row small{display:block;font-size:8px;color:#a8aab4;letter-spacing:1.3px;margin-top:4px}.mode-arrow{margin-left:auto;color:#c1c1c9}.play-btn{width:100%;height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;background:linear-gradient(110deg,#ffbc52,#ff9e38);border:0;border-radius:7px;color:#25232a;font-family:'Barlow Condensed';font-size:23px;font-weight:900;letter-spacing:2px;box-shadow:0 6px 24px #ff9e3844;transition:transform .15s,filter .15s}.play-btn:hover{transform:translateY(-2px);filter:brightness(1.08)}.play-btn b{font-family:'DM Sans';font-size:22px}.play-hint{margin-top:11px;color:#b5b4be;font-size:7px;letter-spacing:.85px;white-space:nowrap}.play-hint span{color:var(--orange);padding:0 3px}.map-chip{position:absolute;right:6.2%;bottom:7.9%;display:flex;align-items:center;gap:12px;padding:12px 15px;border:1px solid #ffffff27;background:#141720b8;backdrop-filter:blur(12px);border-radius:8px;text-align:left}.map-chip>span:first-child{color:var(--cyan);font-size:22px}.map-chip small,.map-chip b{display:block}.map-chip small{font-size:8px;letter-spacing:1.5px;color:#aeb2bb}.map-chip span:nth-child(2) b{font-family:'Barlow Condensed';font-size:16px;letter-spacing:1px;margin-top:3px}.map-chevron{margin-left:13px;color:#d5d3d5}.menu-decoration{position:absolute;pointer-events:none;border:1px solid #ffffff0b;transform:rotate(36deg)}.decoration-one{right:13%;top:13%;width:180px;height:180px;border-radius:40px}.decoration-two{right:8%;top:18%;width:72px;height:72px;border-radius:20px}
.modal{z-index:5;display:flex;align-items:center;justify-content:center;padding:20px;background:#090b12bf;backdrop-filter:blur(9px)}.hidden{display:none!important}.modal-card{width:min(780px,94vw);max-height:88vh;background:#171a24;border:1px solid #ffffff20;border-radius:15px;box-shadow:0 25px 100px #000b;padding:25px}.modal-head{display:flex;justify-content:space-between;align-items:flex-start}.modal-head h2{font-family:'Barlow Condensed';font-size:33px;letter-spacing:1px;margin:4px 0 0}.modal-head h2 span{font-family:'DM Sans';font-size:11px;background:#343541;color:#f9b344;padding:5px 8px;border-radius:5px;vertical-align:middle;margin-left:4px}.close-btn{width:34px;height:34px;border:1px solid #ffffff24;background:#252833;border-radius:8px;font-size:23px;color:#cacbd2}.roster-tools{display:flex;justify-content:space-between;align-items:center;margin:20px 0 13px}.roster-tools input{width:245px;background:#10121a;border:1px solid #ffffff20;border-radius:7px;padding:10px 12px;color:white;outline:none;font-size:12px}.roster-tools input:focus{border-color:#ffb33e}.roster-tools>span{font-size:9px;color:#9da0aa;letter-spacing:1.3px;font-weight:700}.roster-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;overflow:auto;max-height:55vh;padding-right:4px}.brawler-tile{min-height:80px;text-align:center;border:1px solid #ffffff12;background:#20232e;border-radius:9px;padding:8px 4px 6px;transition:.14s}.brawler-tile:hover,.brawler-tile.selected{border-color:#ffb33e;background:#332b29;transform:translateY(-2px)}.brawler-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;margin:0 auto 5px;color:#23232a;font-size:19px;background:linear-gradient(145deg,var(--c1),var(--c2));box-shadow:inset 0 -6px 8px #0002}.brawler-tile b{display:block;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.brawler-tile small{font-size:7px;color:#a9abb5;letter-spacing:.6px}.map-card{width:min(700px,94vw)}.map-choices{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-top:22px}.map-option{border:1px solid #ffffff20;background:#20232d;border-radius:11px;overflow:hidden;padding:0;text-align:left;transition:.15s}.map-option:hover,.map-option.selected{border-color:#ffb33e;transform:translateY(-3px)}.map-preview{height:125px;position:relative;overflow:hidden;background:linear-gradient(155deg,var(--sky),var(--ground));}.map-preview:before{content:'';position:absolute;inset:15px 20px;background:repeating-linear-gradient(45deg,transparent 0 18px,#00000010 19px 21px)}.map-preview:after{content:'';position:absolute;width:60px;height:25px;left:calc(50% - 30px);top:45%;background:#262a2e88;transform:rotate(-25deg);box-shadow:62px 23px 0 -4px #34353299,-65px -20px 0 4px #33362b88}.map-meta{padding:12px}.map-meta b{font-family:'Barlow Condensed';font-size:18px;letter-spacing:.8px}.map-meta small{display:block;color:#aaaeba;font-size:9px;margin-top:4px;letter-spacing:.3px}.map-option.selected .map-meta b{color:#ffbd53}
.match-hud{z-index:3;pointer-events:none}.hud-top{position:absolute;top:24px;left:0;right:0;display:flex;align-items:flex-start;justify-content:center;gap:12px}.hud-pill{height:39px;padding:0 13px;display:flex;gap:8px;align-items:center;border-radius:7px;background:#141720d9;border:1px solid #ffffff24;box-shadow:0 4px 16px #0004}.hud-pill b{font-family:'Barlow Condensed';font-size:19px}.hud-pill span{font-size:9px;letter-spacing:1px;color:#e6e5e8}.alive-dot{width:7px;height:7px;background:#70e1a3;border-radius:50%;box-shadow:0 0 8px #70e1a3}.hud-map{text-align:center;padding:2px 12px}.hud-map span{font-family:'Barlow Condensed';font-weight:700;font-size:17px;letter-spacing:1.5px;text-shadow:0 2px 6px #000}.hud-map small{display:block;font-size:8px;color:#ddd;letter-spacing:1.6px}.timer{min-width:76px;justify-content:center}.timer span{font-size:16px;color:var(--orange)}.player-hud{position:absolute;left:28px;bottom:25px;width:230px;padding:12px;background:#141720dc;border:1px solid #ffffff26;border-radius:8px}.health-label{display:flex;justify-content:space-between;font-size:9px;font-weight:800;letter-spacing:.8px;margin-bottom:7px}.health-label b{color:#eee;font-size:9px}.health-track{height:9px;background:#493438;border-radius:7px;overflow:hidden}.health-track i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#6fe99c,#b3ef6c);border-radius:8px;transition:width .15s}.ammo-row{display:flex;gap:5px;margin-top:9px}.ammo-row i{width:13px;height:6px;border-radius:5px;background:#ffbc52}.ammo-row i.empty{background:#ffffff24}.controls-hint{position:absolute;bottom:27px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:8px 13px;background:#11141bd9;border:1px solid #ffffff1f;border-radius:6px;color:#bdbdc6;font-size:8px;letter-spacing:1.1px}.controls-hint span{color:#ffb33e;padding:0 5px}.controls-hint kbd{color:#fff;background:#363947;border-radius:3px;padding:2px 5px}.quit-btn{pointer-events:auto;position:absolute;right:22px;top:23px;border:1px solid #ffffff33;background:#141720bb;border-radius:7px;width:37px;height:37px;font-size:17px}.touch-controls{display:none;pointer-events:auto}.result-card{width:min(400px,92vw);text-align:center;padding:32px;background:#181b26;border:1px solid #ffffff22;border-radius:16px;box-shadow:0 25px 90px #000b}.result-kicker{font-size:9px;letter-spacing:2.4px;color:#aaaeba;font-weight:800}.result-icon{font-size:36px;margin-top:12px;color:var(--orange);text-shadow:0 0 28px #ffb33e66}.result-card h2{font-family:'Barlow Condensed';font-weight:900;font-size:62px;line-height:1;margin:4px 0 7px;color:#ffbd52}.result-card h2.loss{color:#ff6e68}.result-card p{color:#c3c4cc;font-size:12px;margin:0 0 22px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid #ffffff18;padding:14px 0;margin-bottom:20px}.result-stats b{display:block;font-family:'Barlow Condensed';font-size:25px}.result-stats span{font-size:8px;letter-spacing:1px;color:#a6a8b2}.menu-return{background:transparent;border:0;color:#c2c3cc;font-size:9px;letter-spacing:1.7px;font-weight:800;margin-top:14px}.toast{position:absolute;z-index:6;left:50%;top:18%;transform:translateX(-50%);padding:10px 17px;border-radius:7px;background:#171a24ed;border:1px solid #ffbd5266;font-size:11px;letter-spacing:.5px;box-shadow:0 8px 30px #0007}
@media(max-width:760px){.topbar{height:66px;padding:0 20px}.brand{font-size:21px}.hero-copy{left:7%;top:14%}.hero-copy h1{font-size:clamp(64px,17vw,95px);margin:18px 0}.hero-copy p{font-size:12px}.home-bottom{left:6%;right:6%;bottom:5%;gap:12px;align-items:stretch}.home-card{width:46%;padding:12px}.picked-portrait{width:39px;height:39px;font-size:21px}.picked-row{gap:8px}.picked-row h2{font-size:21px}.picked-row span{font-size:7px}.change-btn{font-size:0}.change-btn b{font-size:18px}.stats>div{grid-template-columns:45px 1fr}.play-block{width:54%;align-self:flex-end}.play-btn{height:49px}.play-hint{font-size:6px;letter-spacing:0;white-space:normal;line-height:1.4}.mode-row{gap:7px}.mode-row b{font-size:9px}.mode-row small{font-size:7px}.map-chip{right:6%;bottom:auto;top:76px;padding:8px 10px}.map-chip span:nth-child(2) b{font-size:13px}.map-chip>span:first-child{font-size:17px}.decoration-one{right:0;top:24%;width:120px;height:120px}.decoration-two{right:3%;top:29%;width:55px;height:55px}.profile{font-size:10px}.profile b{margin-left:5px}.modal{padding:10px}.modal-card{padding:18px}.roster-grid{grid-template-columns:repeat(4,1fr);max-height:58vh;gap:6px}.brawler-tile{min-height:70px}.map-choices{gap:8px}.map-preview{height:88px}.map-meta{padding:8px}.map-meta b{font-size:15px}.map-meta small{font-size:8px}.map-card{padding:16px}.hud-top{top:12px;gap:4px}.hud-pill{height:33px;padding:0 8px;gap:5px}.hud-map{padding:2px 5px}.hud-map span{font-size:13px}.hud-map small{font-size:6px}.hud-pill span{font-size:7px}.hud-pill b{font-size:17px}.quit-btn{right:10px;top:57px;width:31px;height:31px}.player-hud{left:12px;bottom:12px;width:175px;padding:9px}.health-label{font-size:8px}.health-label b{font-size:8px}.controls-hint{display:none}.touch-controls{display:block;position:absolute;inset:0}.joystick{position:absolute;left:24px;bottom:25px;width:105px;height:105px;border:1px solid #ffffff54;background:#181b2788;border-radius:50%;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:43px;height:43px;border-radius:50%;background:#d6d1cfaa;border:1px solid #fff9;box-shadow:0 3px 12px #0006}.touch-fire,.touch-super{position:absolute;border-radius:50%;display:grid;place-items:center;pointer-events:auto;touch-action:none}.touch-fire{right:25px;bottom:30px;width:76px;height:76px;background:#ffb33edb;border:2px solid #ffe3a2;color:#29232a;font-size:30px;box-shadow:0 5px 20px #0006}.touch-super{right:98px;bottom:102px;width:48px;height:48px;background:#5ad8d5d9;border:2px solid #c5ffff;color:#182429;font-size:21px}.result-card{padding:25px}.result-card h2{font-size:54px}}
@media(max-height:650px) and (min-width:761px){.hero-copy{top:15%}.hero-copy h1{font-size:78px;margin:14px 0}.home-bottom{bottom:4%}.topbar{height:68px}.map-chip{bottom:4%}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const brawlerNames=['Shelly','Nita','Colt','Bull','Brock','El Primo','Barley','Poco','Rosa','Jessie','Dynamike','Tick','8-Bit','Rico','Darryl','Penny','Carl','Jacky','Gus','Bo','Emz','Stu','Piper','Pam','Frank','Bibi','Bea','Nani','Edgar','Griff','Grom','Bonnie','Gale','Colette','Belle','Ash','Lola','Sam','Mandy','Maisie','Hank','Pearl','Larry & Lawrie','Angelo','Berry','Clancy','Moe','Juju','Shade','Meeple','Ollie','Finx','Lumi','Kaze','Trunk','Spike','Crow','Leon','Sandy','Amber','Meg','Chester','Gray','Willow','Doug','Chuck','Charlie','Mico','Melodie','Lily','Draco','Kenji','Mina','Jae-yong','Alli','R-T','Eve','Janet','Otis','Buster','Fang','Buzz','Squeak','Sprout','Max','Mr. P','Gene','Tara','Mortis','Byron','Lou','Ruffs','Surge','Kit','Cordelius','Hank Jr.','Rodeo','Vex','Nova','Rumble','Ziggy','Trix','Bolt','Doodle','Ranger','Zara','Flint'];
const icons=['✦','☄','⚡','✹','✧','☀','♨','♪','❀','✿','☄','☠','▣','◉','◍','✦'];
const palettes=[['#ffd371','#dc785d'],['#80e4ad','#288b79'],['#79c6ff','#356ac6'],['#ff8970','#a93448'],['#f5e194','#c57835'],['#a6a0ff','#6654a0'],['#ff9fc4','#c34e83'],['#bde879','#49935f']];
const maps=[
 {name:'SUNSET CANYON',sub:'Open sightlines · scattered cover',sky:'#eba85f',ground:'#c9854c',edge:'#8d5539',accent:'#e3ae63',wall:'#9f613d',bush:'#47774d',water:'#58aab0'},
 {name:'NEON GARDENS',sub:'Dense brush · narrow lanes',sky:'#74bca3',ground:'#638d67',edge:'#3b614e',accent:'#85b878',wall:'#4e6651',bush:'#2e754f',water:'#4ca5ad'},
 {name:'FROSTFALL FORT',sub:'Icy paths · frozen pools',sky:'#a8d1dd',ground:'#87aeba',edge:'#587d91',accent:'#cee4df',wall:'#617d8a',bush:'#54837b',water:'#4a92b1'}
];
let selected=0,mapIndex=0,mode='menu',last=0,elapsed=0,raf=0,keys={},pointer={x:0,y:0,down:false},player,bots=[],bullets=[],pickups=[],obstacles=[],particles=[],kills=0,alive=0,storm=0,joy={x:0,y:0},joystickActive=false,ammo=3,ammoClock=0,toastTimer=0;
let W=innerWidth,H=innerHeight,DPR=1,scale=20,center={x:0,y:0};
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);scale=Math.min(W/34,H/21);center={x:W*.5,y:H*.53};}
addEventListener('resize',resize);resize();
function colorFor(i){return palettes[i%palettes.length]}
function portrait(i){return icons[i%icons.length]}
function buildRoster(){const grid=$('#rosterGrid');grid.innerHTML='';brawlerNames.forEach((name,i)=>{const c=colorFor(i),tile=document.createElement('button');tile.className='brawler-tile'+(i===selected?' selected':'');tile.dataset.name=name.toLowerCase();tile.innerHTML=`<span class="brawler-icon" style="--c1:${c[0]};--c2:${c[1]}">${portrait(i)}</span><b>${name}</b><small>${['DAMAGE','TANK','SUPPORT','CONTROLLER'][i%4]}</small>`;tile.onclick=()=>selectBrawler(i);grid.appendChild(tile)});$('#rosterCount').textContent=brawlerNames.length}
function selectBrawler(i){selected=i;const c=colorFor(i);$('#selectedName').textContent=brawlerNames[i];$('#selectedPortrait').textContent=portrait(i);$('#selectedPortrait').style.background=`linear-gradient(145deg,${c[0]},${c[1]})`;$('#selectedType').textContent=['THE ALL-ROUNDER','HEAVY HITTER','QUICK STRIKER','ARENA ACE'][i%4];$$('.brawler-tile').forEach((el,j)=>el.classList.toggle('selected',j===i));$('#roster').classList.add('hidden')}
function buildMaps(){const box=$('#mapChoices');box.innerHTML='';maps.forEach((m,i)=>{const el=document.createElement('button');el.className='map-option'+(i===mapIndex?' selected':'');el.innerHTML=`<div class="map-preview" style="--sky:${m.sky};--ground:${m.ground}"></div><div class="map-meta"><b>${m.name}</b><small>${m.sub}</small></div>`;el.onclick=()=>{mapIndex=i;$('#mapName').textContent=m.name;$$('.map-option').forEach((e,j)=>e.classList.toggle('selected',j===i));$('#maps').classList.add('hidden')};box.appendChild(el)})}
buildRoster();buildMaps();
$('#openRoster').onclick=()=>$('#roster').classList.remove('hidden');$('#mapButton').onclick=()=>$('#maps').classList.remove('hidden');$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).classList.add('hidden'));$('#rosterSearch').addEventListener('input',e=>$$('.brawler-tile').forEach(t=>t.style.display=t.dataset.name.includes(e.target.value.toLowerCase())?'':'none'));
function showToast(text){const el=$('#toast');el.textContent=text;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),1800)}
function project(x,y,z=0){const s=scale;return{x:center.x+(x-y)*.70*s,y:center.y+(x+y)*.37*s-z*s}}
function unproject(px,py){const a=(px-center.x)/(.70*scale),b=(py-center.y)/(.37*scale);return{x:(a+b)/2,y:(b-a)/2}}
function rnd(a,b){return a+Math.random()*(b-a)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function within(x,y){return x>-.1&&y>-.1&&x<24.1&&y<20.1}
function createMap(){obstacles=[];pickups=[];const solid=[ [4,4,'rock'],[8,3,'bush'],[13,4,'wall'],[18,3,'bush'],[21,6,'rock'],[5,9,'bush'],[10,8,'wall'],[15,9,'bush'],[19,11,'wall'],[3,14,'rock'],[8,15,'wall'],[13,14,'bush'],[18,16,'rock'],[21,14,'bush'],[5,18,'bush'],[11,18,'rock'] ];
 solid.forEach(([x,y,type],i)=>{if((i+mapIndex)%5===0)type='box';obstacles.push({x:x+rnd(-.3,.3),y:y+rnd(-.3,.3),type,r:type==='wall'?.9:type==='bush'?.72:.62,h:type==='wall'?.8:type==='rock'?.8:.45,hp:type==='box'?3:Infinity})});
 for(let i=0;i<5;i++){let p={x:rnd(2,22),y:rnd(2,18),type:'box',r:.52,h:.52,hp:3};if(!nearObstacle(p))obstacles.push(p)}
}
