(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const names=['Shelly','Nita','Colt','Bull','Brock','El Primo','Barley','Poco','Rosa','Jessie','Dynamike','Tick','8-Bit','Rico','Darryl','Penny','Carl','Jacky','Gus','Bo','Emz','Stu','Piper','Pam','Frank','Bibi','Bea','Nani','Edgar','Griff','Grom','Bonnie','Gale','Colette','Belle','Ash','Lola','Sam','Mandy','Maisie','Hank','Pearl','Larry & Lawrie','Angelo','Berry','Clancy','Moe','Juju','Shade','Meeple','Ollie','Finx','Lumi','Kaze','Trunk','Spike','Crow','Leon','Sandy','Amber','Meg','Chester','Gray','Willow','Doug','Chuck','Charlie','Mico','Melodie','Lily','Draco','Kenji','Mina','Jae-yong','Alli','R-T','Eve','Janet','Otis','Buster','Fang','Buzz','Squeak','Sprout','Max','Mr. P','Gene','Tara','Mortis','Byron','Lou','Ruffs','Surge','Kit','Cordelius','Hank Jr.','Rodeo','Vex','Nova','Rumble','Ziggy','Trix','Bolt','Doodle','Ranger','Zara','Flint'];
const icons=['✦','☄','⚡','✹','✧','☀','♨','♪','❀','✿','☄','☠','▣','◉','◍','✦'],palettes=[['#ffd371','#dc785d'],['#80e4ad','#288b79'],['#79c6ff','#356ac6'],['#ff8970','#a93448'],['#f5e194','#c57835'],['#a6a0ff','#6654a0'],['#ff9fc4','#c34e83'],['#bde879','#49935f']];
const maps=[{name:'SUNSET CANYON',sub:'Open sightlines · scattered cover',sky:'#eba85f',ground:'#c9854c',edge:'#8d5539',accent:'#e3ae63',wall:'#9f613d',bush:'#47774d'},{name:'NEON GARDENS',sub:'Dense brush · narrow lanes',sky:'#74bca3',ground:'#638d67',edge:'#3b614e',accent:'#85b878',wall:'#4e6651',bush:'#2e754f'},{name:'FROSTFALL FORT',sub:'Icy paths · frozen pools',sky:'#a8d1dd',ground:'#87aeba',edge:'#587d91',accent:'#cee4df',wall:'#617d8a',bush:'#54837b'}];
let selected=0,mapIndex=0,mode='menu',last=0,elapsed=0,raf=0,keys={},pointer={x:0,y:0,down:false},player,bots=[],bullets=[],pickups=[],obstacles=[],particles=[],kills=0,alive=0,storm=0,joy={x:0,y:0},joystickActive=false,ammoClock=0,toastTimer=0,W=innerWidth,H=innerHeight,DPR=1,scale=20,center={x:0,y:0};
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);scale=Math.min(W/34,H/21);center={x:W*.5,y:H*.53}}addEventListener('resize',resize);resize();
const colorFor=i=>palettes[i%palettes.length],portrait=i=>icons[i%icons.length],rnd=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),within=(x,y)=>x>-.1&&y>-.1&&x<24.1&&y<20.1;
function project(x,y,z=0){return{x:center.x+(x-y)*.70*scale,y:center.y+(x+y)*.37*scale-z*scale}}function unproject(px,py){let a=(px-center.x)/(.70*scale),b=(py-center.y)/(.37*scale);return{x:(a+b)/2,y:(b-a)/2}}
function buildRoster(){const grid=$('#rosterGrid');grid.innerHTML='';names.forEach((name,i)=>{const c=colorFor(i),t=document.createElement('button');t.className='brawler-tile'+(i===selected?' selected':'');t.dataset.name=name.toLowerCase();t.innerHTML=`<span class="brawler-icon" style="--c1:${c[0]};--c2:${c[1]}">${portrait(i)}</span><b>${name}</b><small>${['DAMAGE','TANK','SUPPORT','CONTROLLER'][i%4]}</small>`;t.onclick=()=>selectBrawler(i);grid.appendChild(t)});$('#rosterCount').textContent=names.length}
function selectBrawler(i){selected=i;const c=colorFor(i);$('#selectedName').textContent=names[i];$('#selectedPortrait').textContent=portrait(i);$('#selectedPortrait').style.background=`linear-gradient(145deg,${c[0]},${c[1]})`;$('#selectedType').textContent=['THE ALL-ROUNDER','HEAVY HITTER','QUICK STRIKER','ARENA ACE'][i%4];all('.brawler-tile').forEach((e,j)=>e.classList.toggle('selected',j===i));$('#roster').classList.add('hidden')}
function buildMaps(){const box=$('#mapChoices');box.innerHTML='';maps.forEach((m,i)=>{const e=document.createElement('button');e.className='map-option'+(i===mapIndex?' selected':'');e.innerHTML=`<div class="map-preview" style="--sky:${m.sky};--ground:${m.ground}"></div><div class="map-meta"><b>${m.name}</b><small>${m.sub}</small></div>`;e.onclick=()=>{mapIndex=i;$('#mapName').textContent=m.name;all('.map-option').forEach((x,j)=>x.classList.toggle('selected',j===i));$('#maps').classList.add('hidden')};box.appendChild(e)})}
