const canvas=$('#game'),ctx=canvas.getContext('2d');
let W=0,H=0,selected=0,mapIndex=0,mode='menu',obstacles=[],bullets=[],particles=[],bots=[],player,pickups=[],keys={},elapsed=0,alive=10,kills=0,storm=0,last=0,raf,toastTimer;
