function resize(){let d=window.devicePixelRatio||1;W=innerWidth;H=innerHeight;canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();
function project(x,y,z=0){let cx=W*.52,cy=H*.48;return{x:cx+(x-y)*31, y:cy+(x+y)*15-z*20}}
function unproject(sx,sy){let dx=(sx-W*.52)/31,dy=(sy-H*.48)/15;return{x:(dy+dx)/2,y:(dy-dx)/2}}
function within(x,y){return x>.35&&x<23.65&&y>.35&&y<19.65}
