function drawMenuBg(){let m=maps[mapIndex],cx=W*.72,cy=H*.62;ctx.fillStyle=m.sky;ctx.fillRect(0,0,W,H);for(let i=0;i<70;i++){let x=(i*137)%W,y=(i*83)%H;ctx.fillStyle=i%3?'#ffffff09':'#ffffff12';ctx.fillRect(x,y,1+(i%4),1+(i%4))}ctx.fillStyle=m.floor;for(let y=-10;y<35;y+=1.5)for(let x=-10;x<30;x+=1.5){let p=project(x,y);ctx.fillStyle=((Math.floor(x)+Math.floor(y))%2)?m.floor:'#ffffff06';ctx.fillRect(p.x-18,p.y-9,36,18)}for(let i=0;i<10;i++){let p=project(2+i*2.4,10+(i%3)*1.2);ctx.save();ctx.translate(p.x,p.y);ctx.scale(.7,.7);ctx.fillStyle=i%2?'#46695b':'#35594e';ctx.fillRect(-28,-36,56,31);ctx.fillStyle='#66866d';ctx.beginPath();ctx.arc(0,-40,29,0,Math.PI*2);ctx.fill();ctx.restore()}ctx.fillStyle='#00000018';ctx.fillRect(0,0,W,H)}
