function drawActor(a){let p=project(a.x,a.y,.45),s=1.15;if(!a.alive)return;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='#00000038';ctx.beginPath();ctx.ellipse(0,8,18,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=a.flash>0?'#fff':a.light;ctx.beginPath();ctx.arc(0,-18,13,0,Math.PI*2);ctx.fill();ctx.fillStyle=a.dark||'#3b3b49';ctx.beginPath();ctx.moveTo(-11,-12);ctx.quadraticCurveTo(-13,8,-7,13);ctx.lineTo(7,13);ctx.quadraticCurveTo(13,8,11,-12);ctx.closePath();ctx.fill();ctx.fillStyle='#242633';ctx.fillRect(-8,9,6,15);ctx.fillRect(2,9,6,15);ctx.strokeStyle=a.light;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(10,-8);ctx.lineTo(18,-15);ctx.stroke();ctx.restore();if(!a.isPlayer){ctx.fillStyle='#10131b';ctx.fillRect(p.x-16,p.y-52,32,4);ctx.fillStyle='#68d99a';ctx.fillRect(p.x-16,p.y-52,32*(a.hp/a.maxHp),4)}}
function drawScene(){if(mode==='menu'){drawMenuBg();return}let m=maps[mapIndex];ctx.fillStyle=m.sky;ctx.fillRect(0,0,W,H);for(let y=0;y<20;y++)for(let x=0;x<24;x++){let p=project(x,y);tile(p,62,31,(x+y)%2?m.floor:m.grid)}let scenery=[...obstacles.map(o=>({z:1,...o,type:'obstacle'})),...pickups.map(p=>({z:2,...p,type:'pickup'})),...bots.filter(b=>b.alive).map(b=>({z:3,...b,type:'actor'})),{z:3,...player,type:'actor'}].sort((a,b)=>a.x+a.y-(b.x+b.y));scenery.forEach(o=>{if(o.type==='obstacle'){let p=project(o.x,o.y,.25);if(o.type==='bush'){ctx.fillStyle='#668c55';ctx.beginPath();ctx.arc(p.x,p.y-8,o.r*17,0,Math.PI*2);ctx.fill()}else if(o.type==='rock'){ctx.fillStyle='#77766f';ctx.beginPath();ctx.moveTo(p.x-20,p.y);ctx.lineTo(p.x-13,p.y-23);ctx.lineTo(p.x+12,p.y-20);ctx.lineTo(p.x+22,p.y);ctx.closePath();ctx.fill()}else {ctx.fillStyle='#d09a58';ctx.fillRect(p.x-18,p.y-30,36,30);ctx.strokeStyle='#8d663c';ctx.strokeRect(p.x-18,p.y-30,36,30)}}else if(o.type==='pickup'){let p=project(o.x,o.y,.5);ctx.fillStyle=o.type==='cube'?'#69ddc9':'#ef6262';ctx.fillRect(p.x-7,p.y-11,14,14)}else if(o.type==='actor')drawActor(o)});bullets.forEach(b=>{let p=project(b.x,b.y,.45);ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/.6,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*12,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1});if(storm>0){ctx.strokeStyle=`rgba(112,58,196,${.35+.5*storm})`;ctx.lineWidth=25;ctx.strokeRect(W*.5-100-storm*130,H*.5-90-storm*90,200+storm*260,180+storm*180)}}
function spawnActor(i){let pl=i===-1,cs=palette[i%palette.length];return{x:rnd(2,22),y:rnd(2,18),radius:.42,speed:pl?4.2:rnd(3.2,4),maxHp:pl?1000:rnd(650,950),hp:pl?1000:650,ammo:pl?3:rnd(1,3)|0,reload:0,super:0,alive:true,attack:0,invuln:0,flash:0,angle:0,light:cs[0],dark:cs[1],isPlayer:pl,name:pl?baseNames[selected]:baseNames[(i+11)%108],wander:rnd(0,6.28),aiTimer:rnd(.2,.7)}}
function startMatch(){$('#home').classList.add('hidden');$('#matchHud').classList.remove('hidden');$('#result').classList.add('hidden');makeObstacles();pickups=[];bullets=[];particles=[];elapsed=0;kills=0;storm=0;alive=10;player=spawnActor(-1);player.x=12;player.y=10;bots=[];for(let i=0;i<9;i++){let b=spawnActor(i);do{b.x=rnd(1.5,22.5);b.y=rnd(1.5,18)}while(dist(b,player)<4||obstacles.some(o=>dist(b,o)<2));bots.push(b)}$('#aliveCount').textContent='10';$('#hudMapName').textContent=maps[mapIndex].name;$('#hudPlayerName').textContent=player.name.toUpperName?player.name.toUpperName():player.name.toUpperCase();$('#healthText').textContent='1000 / 1000';$('#healthBar').style.width='100%';mode='playing';last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function finish(win){if(mode!=='playing')return;mode='ended';cancelAnimationFrame(raf);$('#matchHud').classList.add('hidden');$('#result').classList.remove('hidden');$('#resultTitle').textContent=win?'VICTORY':'DEFEATED';$('#resultCopy').textContent=win?'You are the last brawler standing.':'The arena got the better of you.';$('#resultIcon').textContent=win?'✦':'×';$('#resultKicker').textContent=win?'MATCH WON':'MATCH OVER';$('#resultRank').textContent=win?'#1':`#${Math.max(2,11-alive)}`;$('#resultKOs').textContent=kills;$('#resultTime').textContent=timeText(elapsed)}
function moveActor(a,dx,dy){let nx=a.x+dx,ny=a.y+dy;if(!blocked(nx,a.y,a.radius))a.x=nx;if(!blocked(a.x,ny,a.radius))a.y=ny;a.x=clamp(a.x,.35,23.65);a.y=clamp(a.y,.35,19.65)}
