function shoot(){if(mode!=='playing'||player.ammo<=0)return;let aim=unproject(pointer.x,pointer.y),angle=Math.atan2(aim.y-player.y,aim.x-player.x);if(dist(aim,player)<.2){let t=targetFor(player);if(t)angle=Math.atan2(t.y-player.y,t.x-player.x)}player.angle=angle;player.ammo--;player.reload=.5;for(let i=0;i<3;i++){let ang=angle+(i-1)*.11;bullets.push({x:player.x,y:player.y,vx:Math.cos(ang)*13,vy:Math.sin(ang)*13,life:.65,damage:135,color:'#ffe090',owner:player,r:.15})}updateAmmo()}
